(()=>{'use strict';const reduce=matchMedia('(prefers-reduced-motion:reduce)');const surfaces=[...document.querySelectorAll('.home-needs,.restored-breather,.community-breather,.hardware,.manufacture,.logos,.testimonials,.faq')];const rows=surfaces.map(el=>{const wrap=document.createElement('div');wrap.className='entry-shell';el.before(wrap);wrap.append(el);el.classList.add('entry-surface');return[wrap,el]});let frame=0;function paint(){frame=0;for(const [wrap,el] of rows){let r=wrap.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight*1.15)continue;let p=reduce.matches?1:Math.max(0,Math.min(1,(innerHeight-r.top)/(innerHeight*.83)));let e=1-Math.pow(1-p,3);el.style.setProperty('--entry-scale',.92+.08*e);el.style.setProperty('--entry-y',(1-e)*38+'px');el.style.setProperty('--entry-blur',(1-e)*1.8+'px');el.style.setProperty('--entry-radius',(1-e)*25+'px')}}function queue(){if(!frame)frame=requestAnimationFrame(paint)}addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);reduce.addEventListener('change',queue);paint()})();
